mapper.select:
select conf.industry_id, vconf.app_ver_code, vconf.app_ver_desc, vconf.banner_id,
vconf.img_url, vconf.create_time, vconf.update_time, vconf.creator, vconf.modifier, vconf.status, vconf.delete_flag,
conf.industry_name, conf.industry_code, rel.industry_view_id, rel.view_name, rel.page_id, rel.sort, rel.display_type
from sys_industry_ver_conf as vconf
INNER JOIN sys_industry_view_rel as rel on vconf.industry_code = rel.industry_code and  vconf.app_ver_code = rel.app_ver_code
inner join sys_industry_conf as conf on vconf.industry_code = conf.industry_code and vconf.accept_node = conf.accept_node

	vconf.delete_flag = '0'
	AND conf.delete_flag='0'

		AND conf.industry_name like CONCAT(CONCAT('%', #{industryName}),'%')


		AND vconf.app_ver_code = #{appVerCode}


		AND vconf.status = #{status}


		AND rel.industry_view_id = #{industryViewId}


		AND vconf.industry_code = #{industryCode}


		AND vconf.accept_node = #{acceptNode}


order by vconf.update_time desc, rel.sort asc;

select industry_view_id, industry_view_type, topic_type, view_name as industryViewName, display_type
from sys_industry_view_rel
where industry_code = #{industryCode}
  and industry_view_id = #{industryViewId}
  and industry_view_type = #{industryViewType}
  and app_ver_code = #{appVerCode}

SELECT banner_title, banner_id, banner_type
FROM sys_industry_ver_conf
WHERE
	industry_code = #{industryCode}
  and app_ver_code = #{appVerCode}
  and accept_node = #{platformCode}
  and delete_flag = 0
